def subtractIntervals(keep, remove):
    res = []
    j = 0
    for s, e in keep:
        cur = s
        while j < len(remove) and remove[j][1] <= cur:
            j += 1
        k = j
        while k < len(remove) and remove[k][0] < e:
            if remove[k][0] > cur:
                res.append([cur, remove[k][0]])
            cur = max(cur, remove[k][1])
            if cur >= e:
                break
            k += 1
        if cur < e:
            res.append([cur, e])
        j = k
    return res
